package net.neoforged.neoforge.client.event;
import net.minecraft.server.packs.resources.ResourceManager;import net.minecraft.client.renderer.ShaderInstance;import java.util.*;import java.util.function.Consumer;
public class RegisterShadersEvent {private final ResourceManager resources;public boolean defer;public int registered;private final List<Runnable> callbacks=new ArrayList<>();public RegisterShadersEvent(ResourceManager r){resources=r;}public ResourceManager getResourceProvider(){return resources;}public void registerShader(ShaderInstance shader,Consumer<ShaderInstance> ready){registered++;if(defer)callbacks.add(()->ready.accept(shader));else ready.accept(shader);}public void finish(){for(Runnable callback:List.copyOf(callbacks))callback.run();callbacks.clear();}}
